    async consultAPI(input) {
        try {
            const response = await fetch(this.config.apiURL, {
                method: "POST",
                headers: {
                    "Authorization": `Bearer ${this.config.apiKey}`,
                    "Content-Type": "application/json"
                },
                body: JSON.stringify({
                    model: this.config.model,
                    messages: [{ role: "system", content: "You are AJ, an elite AR Assistant. Be brief. Token conservation is priority. No fillers." }, { role: "user", content: input }]
                })
            });
            const data = await response.json();
            return data.choices[0].message.content;
        } catch (e) { return "API offline. Local core active."; }
    },
    async processInput(input) {
        const cleanInput = input.toLowerCase().trim();
        if (this.logicLibrary[cleanInput]) {
            return this.logicLibrary[cleanInput]();
        }
        return await this.consultAPI(input);
    }
